CREATE VIEW [dbo].[SpostamentiPlan] AS  SELECT idmoveplan, identificativo as codice, mobili.modello as Nm, luogoprov, tipoprov, luogodest, tipodest, data, status, idmove, idddt, dataplan, ord, tecnici.nometecnico from (moveplan INNER JOIN mobili ON mobili.idmobile=moveplan.codiceoggetto) LEFT JOIN tecnici on tecnici.idtecnico=moveplan.idtecnico WHERE tipooggetto=0 UNION SELECT idmoveplan,matricola as codice, schede.nome as Nm,luogoprov, tipoprov, luogodest, tipodest, data, status, idmove, idddt, dataplan, ord, tecnici.nometecnico from (moveplan INNER JOIN schede ON schede.idscheda=moveplan.codiceoggetto) LEFT JOIN tecnici on tecnici.idtecnico=moveplan.idtecnico WHERE tipooggetto=1 UNION SELECT idmoveplan, identificativo as codice, dedicati.nome as Nm,luogoprov, tipoprov, luogodest, tipodest, data, status, idmove, idddt, dataplan, ord, tecnici.nometecnico  from (moveplan INNER JOIN dedicati ON dedicati.iddedicato=moveplan.codiceoggetto) LEFT JOIN tecnici on tecnici.idtecnico=moveplan.idtecnico WHERE tipooggetto= 2 UNION SELECT idmoveplan,matricola as codice, accessori.nome as Nm,luogoprov, tipoprov, luogodest, tipodest, data, status, idmove, idddt, dataplan, ord,tecnici.nometecnico  from (moveplan INNER JOIN accessori ON accessori.idaccessorio=moveplan.codiceoggetto) LEFT JOIN tecnici on tecnici.idtecnico=moveplan.idtecnico WHERE tipooggetto=3 UNION SELECT idmoveplan,matricola as codice, distribut.nome as Nm,luogoprov, tipoprov, luogodest, tipodest, data, status, idmove, idddt, dataplan, ord,tecnici.nometecnico  from (moveplan INNER JOIN distribut ON distribut.iddistributore=moveplan.codiceoggetto) LEFT JOIN tecnici on tecnici.idtecnico=moveplan.idtecnico WHERE tipooggetto=15
GO
